function validate([s, words]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses lowercase English letters only.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'Each word needs 1 to 100 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Each word uses lowercase English letters only.';
  }
  return null;
}

