function expressiveWords(s, words) {
  let count = 0;
  for (const word of words) {
    let i = 0;
    let j = 0;
    let stretchy = true;
    while (stretchy && i < s.length && j < word.length) {
      const letter = s[i];
      if (word[j] !== letter) {
        stretchy = false;
        break;
      }
      const startS = i;
      while (i < s.length && s[i] === letter) {
        i++;
      }
      const startWord = j;
      while (j < word.length && word[j] === letter) {
        j++;
      }
      const runS = i - startS;
      const runWord = j - startWord;
      if (runS < runWord || (runS !== runWord && runS < 3)) {
        stretchy = false;
      }
    }
    if (stretchy && i === s.length && j === word.length) {
      count++;
    }
  }
  return count;
}

