function expressiveWords(s, words) {
  const groups = (text) => text.match(/(.)\1*/g).map(run => [run[0], run.length]);
  const target = groups(s);
  let total = 0;
  for (const word of words) {
    const parts = groups(word);
    if (parts.length !== target.length) continue;
    let ok = true;
    for (let k = 0; k < parts.length; k++) {
      const [letter, size] = parts[k];
      const [wanted, goal] = target[k];
      if (letter !== wanted) ok = false;
      else if (size > goal) ok = false;
      else if (size < goal && goal < 3) ok = false;
    }
    if (ok) total++;
  }
  return total;
}

