function generate(rand, size) {
  const large = size === 'large';
  const pool = large ? 'abcdef' : 'abc';
  const runs = [];
  let length = 0;
  const maxLength = large ? 100 : 8;
  while (length < maxLength) {
    let letter = pool[Math.floor(rand() * pool.length)];
    while (runs.length && runs[runs.length - 1][0] === letter) letter = pool[Math.floor(rand() * pool.length)];
    const run = Math.min(maxLength - length, 1 + Math.floor(rand() * (large ? 6 : 4)));
    runs.push([letter, run]);
    length += run;
    if (!large && rand() < 0.25) break;
  }
  const s = runs.map(([c, n]) => c.repeat(n)).join('');
  const count = large ? 100 : 1 + Math.floor(rand() * 5);
  const words = [];
  for (let w = 0; w < count; w++) {
    const mode = rand();
    let word = '';
    if (mode < 0.15) {
      const n = 1 + Math.floor(rand() * (large ? 100 : 6));
      for (let k = 0; k < n; k++) word += pool[Math.floor(rand() * pool.length)];
    } else {
      const parts = runs.map(([c, n]) => [c, n >= 3 ? 1 + Math.floor(rand() * n) : n]);
      if (mode < 0.55) {
        const k = Math.floor(rand() * parts.length);
        const change = rand();
        if (change < 0.35) parts[k][1] += 1;
        else if (change < 0.6 && parts[k][1] > 1) parts[k][1] -= 1;
        else if (change < 0.8) parts[k][0] = pool[Math.floor(rand() * pool.length)];
        else if (parts.length > 1) parts.splice(k, 1);
      }
      word = parts.map(([c, n]) => c.repeat(n)).join('').slice(0, 100);
    }
    words.push(word);
  }
  return [s, words];
}
